    mov.u32 %r10, %ntid.x;
    mov.u32 %r11, %tid.x;           // tx
    mad.lo.u32 %r12, %r9, %r10, %r11; // col
    setp.ge.u32 %p1, %r8, %r1;
    setp.ge.u32 %p2, %r12, %r2;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;
    mov.u32 %r13, %ctaid.z;          // split-k index
    add.u32 %r14, %r3, %r4;
    sub.u32 %r14, %r14, 1;
    div.u32 %r14, %r14, %r4;         // k_chunk = ceil(K / SPLIT_K)
    mul.lo.u32 %r15, %r13, %r14;     // k_start
