    add.u32 %r25, %r20, %r22;        // rA_base = sA + ty*64
    add.u32 %r26, %r21, %r23;        // rB_base = sB + tx*4
    mov.f32 %f1, 0f00000000;         // acc
    mov.u32 %r17, %r15;              // k_tile = k_start
