    @%p5 bra K_LOOP_END;
    add.u32 %r18, %r17, %r11;        // a_k = k_tile + tx
    add.u32 %r19, %r17, %r7;         // b_k = k_tile + ty
    setp.lt.u32 %p6, %r18, %r16;
    setp.lt.u32 %p7, %r19, %r16;
    mov.f32 %f2, 0f00000000;
    cvt.u64.u32 %rd13, %r18;
    mul.lo.u64 %rd14, %rd13, 4;
    add.u64 %rd15, %rd8, %rd14;
    @%p6 ld.global.f32 %f2, [%rd15];
    mov.f32 %f3, 0f00000000;
    cvt.u64.u32 %rd16, %r19;
    mul.lo.u64 %rd17, %rd16, %rd12;
    add.u64 %rd18, %rd2, %rd17;
    add.u64 %rd18, %rd18, %rd10;
    @%p7 ld.global.f32 %f3, [%rd18];
    add.u32 %r27, %r20, %r24;        // sA store addr
    st.shared.f32 [%r27], %f2;
    add.u32 %r28, %r21, %r24;        // sB store addr
    st.shared.f32 [%r28], %f3;
    bar.sync 0;
    ld.shared.f32 %f4, [%r25+0];
    ld.shared.f32 %f5, [%r26+0];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+4];
    ld.shared.f32 %f5, [%r26+64];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+8];
    ld.shared.f32 %f5, [%r26+128];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+12];
    ld.shared.f32 %f5, [%r26+192];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+16];
    ld.shared.f32 %f5, [%r26+256];
