    ld.shared.f32 %f4, [%r25+28];
    ld.shared.f32 %f5, [%r26+448];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+32];
    ld.shared.f32 %f5, [%r26+512];
