    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+40];
    ld.shared.f32 %f5, [%r26+640];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+44];
    ld.shared.f32 %f5, [%r26+704];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+48];
    ld.shared.f32 %f5, [%r26+768];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+52];
    ld.shared.f32 %f5, [%r26+832];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+56];
    ld.shared.f32 %f5, [%r26+896];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    ld.shared.f32 %f4, [%r25+60];
    ld.shared.f32 %f5, [%r26+960];
    fma.rn.f32 %f1, %f4, %f5, %f1;
